/// Use comments: $from: <expression> and $to: <expression>
@immutable
class CustomSerialization {
  final String id;

  /// Duration stored as milliseconds in JSON
  final Duration
      timeout; // $from: Duration(milliseconds: (map['timeout'] as int?) ?? 0), $to: timeout.inMilliseconds

  /// Uri stored as string in JSON
  final Uri
      endpoint; // $from: Uri.parse(map['endpoint'] as String? ?? ''), $to: endpoint.toString()

  /// Custom date format (Unix timestamp)
  final DateTime
      timestamp; // $from: DateTime.fromMillisecondsSinceEpoch((map['timestamp'] as int?) ?? 0), $to: timestamp.millisecondsSinceEpoch

  const CustomSerialization({
    required this.id,
    required this.timeout,
    required this.endpoint,
    required this.timestamp,
  });

  CustomSerialization copyWith({
    String? id,
    Duration? timeout,
    Uri? endpoint,
    DateTime? timestamp,
  }) {
    return CustomSerialization(
      id: id ?? this.id,
      timeout: timeout ?? this.timeout,
      endpoint: endpoint ?? this.endpoint,
      timestamp: timestamp ?? this.timestamp,
    );
  }

  Map<String, dynamic> toMap() {
    return {
      'id': id,
      'timeout': timeout.inMilliseconds,
      'endpoint': endpoint.toString(),
      'timestamp': timestamp.millisecondsSinceEpoch,
