      value: $value,
      label: $label
      )''';

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) return true;

    return other is Box<T> && other.value == value && other.label == label;
  }

  @override
  int get hashCode => Object.hash(value, label);
}

/// Class with multiple type parameters
@immutable
class Pair<K, V> {
  final K key;
  final V value;

  const Pair({
    required this.key,
    required this.value,
  });

  Pair<K, V> copyWith({
    K? key,
    V? value,
  }) {
    return Pair<K, V>(
      key: key ?? this.key,
      value: value ?? this.value,
    );
  }

  Map<String, dynamic> toMap() {
    return {
      'key': key,
      'value': value,
    };
  }

  factory Pair.fromMap(Map<String, dynamic> map) {
    return Pair<K, V>(
      key: map['key'] as K,
      value: map['value'] as V,
    );
  }

  String toJson() => json.encode(toMap());

  factory Pair.fromJson(String source) =>
      Pair.fromMap(json.decode(source) as Map<String, dynamic>);

  @override
  String toString() => '''Pair(
      key: $key,
      value: $value
      )''';

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) return true;

    return other is Pair<K, V> && other.key == key && other.value == value;
  }

  @override
  int get hashCode => Object.hash(key, value);
}

