/// Abstract base class
@immutable
abstract class Entity {
  final String id;

  const Entity({
    this.id = '',
  });

  @override
  String toString() => '''Entity(
      id: $id
      )''';

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) return true;

    return other is Entity && other.id == id;
  }

  @override
  int get hashCode => id.hashCode;
}

/// Class extending another
@immutable
class Product extends Entity {
  final String name;
  final double price;

  const Product({
    required this.name,
    required this.price,
  });

  Product copyWith({
    String? name,
    double? price,
  }) {
    return Product(
      name: name ?? this.name,
      price: price ?? this.price,
    );
  }

  Map<String, dynamic> toMap() {
    return {
      'name': name,
      'price': price,
    };
  }

  factory Product.fromMap(Map<String, dynamic> map) {
    T cast<T>(String k) => map[k] is T
        ? map[k] as T
        : throw ArgumentError.value(map[k], k, '$T ← ${map[k].runtimeType}');
    return Product(
      name: cast<String?>('name') ?? '',
      price: cast<num?>('price')?.toDouble() ?? 0.0,
    );
  }

  String toJson() => json.encode(toMap());

  factory Product.fromJson(String source) =>
      Product.fromMap(json.decode(source) as Map<String, dynamic>);

  @override
  String toString() => '''Product(
      name: $name,
      price: $price
      )''';

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) return true;

    return other is Product && other.name == name && other.price == price;
  }

  @override
  int get hashCode => Object.hash(name, price);
}

