// ============================================================================
// COMPLETE EXAMPLE - All features combined
// ============================================================================

/// Comprehensive example showing all generator features
@immutable
class CompleteExample {
  // Primitives
  final String name;
  final int count;
  final double value;
  final bool flag;

  // Nullable primitives
  final String? nickname;
  final int? optionalCount;

  // Enums
  final Status status; // enum
  final Priority? priority; // enum

  // Collections
  final List<String> tags;
  final Map<String, int> scores;
  final Set<String>? categories;

  // Custom types (built-in support)
  final DateTime createdAt;
  final Color themeColor;
  final IconData icon;

  // Nullable custom types
  final DateTime? modifiedAt;
  final Color? accentColor;

  // Nested objects
  final Address address;
  final Address? shippingAddress;
  final List<Address> locations;

  // Collections of custom types
  final List<DateTime> history;
  final List<Color>? colorScheme;

  // Custom serialization
  final Duration
      timeout; // $from: Duration(milliseconds: (map['timeout'] as int?) ?? 1000), $to: timeout.inMilliseconds
  final Uri
      apiUrl; // $from: Uri.parse(map['api_url'] as String? ?? 'https://api.example.com'), $to: apiUrl.toString()

  const CompleteExample({
    required this.name,
    this.count = 0,
    this.value = 0.0,
    this.flag = false,
    this.nickname,
    this.optionalCount,
    required this.status,
    this.priority,
    this.tags = const [],
    this.scores = const {},
    this.categories,
    required this.createdAt,
    required this.themeColor,
    required this.icon,
    this.modifiedAt,
    this.accentColor,
    required this.address,
    this.shippingAddress,
    this.locations = const [],
    this.history = const [],
    this.colorScheme,
    required this.timeout,
    required this.apiUrl,
  });

  static const Object _sentinel = Object();
  CompleteExample copyWith({
    String? name,
    int? count,
    double? value,
    bool? flag,
    Object? nickname = _sentinel,
    Object? optionalCount = _sentinel,
    Status? status,
    Object? priority = _sentinel,
    List<String>? tags,
    Map<String, int>? scores,
    Object? categories = _sentinel,
    DateTime? createdAt,
    Color? themeColor,
    IconData? icon,
    Object? modifiedAt = _sentinel,
    Object? accentColor = _sentinel,
    Address? address,
    Object? shippingAddress = _sentinel,
    List<Address>? locations,
    List<DateTime>? history,
    Object? colorScheme = _sentinel,
    Duration? timeout,
    Uri? apiUrl,
  }) {
    return CompleteExample(
      name: name ?? this.name,
      count: count ?? this.count,
      value: value ?? this.value,
      flag: flag ?? this.flag,
      nickname: nickname == _sentinel ? this.nickname : (nickname as String?),
      optionalCount: optionalCount == _sentinel
          ? this.optionalCount
          : (optionalCount as int?),
      status: status ?? this.status,
      priority: priority == _sentinel ? this.priority : (priority as Priority?),
      tags: tags ?? this.tags,
      scores: scores ?? this.scores,
      categories: categories == _sentinel
          ? this.categories
          : (categories as Set<String>?),
      createdAt: createdAt ?? this.createdAt,
      themeColor: themeColor ?? this.themeColor,
      icon: icon ?? this.icon,
      modifiedAt:
          modifiedAt == _sentinel ? this.modifiedAt : (modifiedAt as DateTime?),
      accentColor:
          accentColor == _sentinel ? this.accentColor : (accentColor as Color?),
      address: address ?? this.address,
      shippingAddress: shippingAddress == _sentinel
          ? this.shippingAddress
          : (shippingAddress as Address?),
      locations: locations ?? this.locations,
      history: history ?? this.history,
      colorScheme: colorScheme == _sentinel
          ? this.colorScheme
          : (colorScheme as List<Color>?),
      timeout: timeout ?? this.timeout,
      apiUrl: apiUrl ?? this.apiUrl,
    );
  }

  Map<String, dynamic> toMap() {
    return {
      'name': name,
      'count': count,
      'value': value,
      'flag': flag,
      'nickname': nickname,
      'optional_count': optionalCount,
      'status': status.name,
      'priority': priority?.name,
      'tags': tags,
      'scores': scores,
      'categories': categories?.toList(),
      'created_at': createdAt.toIso8601String(),
      'theme_color': themeColor.toARGB32(),
      'icon': icon.codePoint,
      'modified_at': modifiedAt?.toIso8601String(),
      'accent_color': accentColor?.toARGB32(),
      'address': address.toMap(),
      'shipping_address': shippingAddress?.toMap(),
      'locations': locations.map((x) => x.toMap()).toList(),
      'history': history.map((x) => x.toIso8601String()).toList(),
      'color_scheme': colorScheme?.map((x) => x.toARGB32()).toList(),
      'timeout': timeout.inMilliseconds,
      'api_url': apiUrl.toString(),
    };
  }

  factory CompleteExample.fromMap(Map<String, dynamic> map) {
    T cast<T>(String k) => map[k] is T
        ? map[k] as T
        : throw ArgumentError.value(map[k], k, '$T ← ${map[k].runtimeType}');
    return CompleteExample(
      name: cast<String?>('name') ?? '',
      count: cast<num?>('count')?.toInt() ?? 0,
      value: cast<num?>('value')?.toDouble() ?? 0.0,
      flag: cast<bool?>('flag') ?? false,
      nickname: cast<String?>('nickname'),
      optionalCount: cast<num?>('optional_count')?.toInt(),
      status: Status.values
          .byName(cast<String?>('status') ?? Status.values.first.name),
      priority: map['priority'] != null
          ? Priority.values
              .byName(cast<String?>('priority') ?? Priority.values.first.name)
          : null,
      tags: List<String>.from(
          cast<Iterable<dynamic>?>('tags') ?? const <String>[]),
      scores: Map<String, int>.from(
          cast<Map<dynamic, dynamic>?>('scores') ?? const {}),
      categories: map['categories'] != null
          ? Set<String>.from(cast<Iterable<dynamic>>('categories'))
          : null,
      createdAt: DateTime.parse(cast<String>('created_at')),
      themeColor: Color(cast<int>('theme_color')),
      icon: IconData(cast<int>('icon')),
      modifiedAt: map['modified_at'] != null
          ? DateTime.parse(cast<String>('modified_at'))
          : null,
      accentColor:
          map['accent_color'] != null ? Color(cast<int>('accent_color')) : null,
      address:
          Address.fromMap(Map.from(cast<Map<dynamic, dynamic>>('address'))),
      shippingAddress: map['shipping_address'] != null
          ? Address.fromMap(
              Map.from(cast<Map<dynamic, dynamic>>('shipping_address')))
          : null,
      locations: List<Address>.from(cast<Iterable<dynamic>?>('locations')?.map(
              (x) => Address.fromMap(Map.from(x as Map<dynamic, dynamic>))) ??
          const <Address>[]),
      history: List<DateTime>.from(cast<Iterable<dynamic>?>('history')
              ?.map((x) => DateTime.parse(x as String? ?? '')) ??
          const <DateTime>[]),
      colorScheme: map['color_scheme'] != null
          ? List<Color>.from(cast<Iterable<dynamic>>('color_scheme')
              .map((x) => Color((x as num?)?.toInt() ?? 0)))
          : null,
      timeout: Duration(milliseconds: (map['timeout'] as int?) ?? 1000),
      apiUrl: Uri.parse(map['api_url'] as String? ?? 'https://api.example.com'),
    );
  }

  String toJson() => json.encode(toMap());

  factory CompleteExample.fromJson(String source) =>
      CompleteExample.fromMap(json.decode(source) as Map<String, dynamic>);

  @override
  String toString() {
    return '''CompleteExample(
      name: $name,
      count: $count,
      value: $value,
      flag: $flag,
      nickname: $nickname,
      optionalCount: $optionalCount,
      status: $status,
      priority: $priority,
      tags: $tags,
      scores: $scores,
      categories: $categories,
      createdAt: $createdAt,
      themeColor: $themeColor,
      icon: $icon,
      modifiedAt: $modifiedAt,
      accentColor: $accentColor,
      address: $address,
      shippingAddress: $shippingAddress,
      locations: $locations,
      history: $history,
      colorScheme: $colorScheme,
      timeout: $timeout,
      apiUrl: $apiUrl
      )''';
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) return true;
    final collectionEquals = const DeepCollectionEquality().equals;

    return other is CompleteExample &&
        other.name == name &&
        other.count == count &&
        other.value == value &&
        other.flag == flag &&
        other.nickname == nickname &&
        other.optionalCount == optionalCount &&
        other.status == status &&
        other.priority == priority &&
        collectionEquals(other.tags, tags) &&
        collectionEquals(other.scores, scores) &&
        collectionEquals(other.categories, categories) &&
        other.createdAt == createdAt &&
        other.themeColor == themeColor &&
        other.icon == icon &&
        other.modifiedAt == modifiedAt &&
        other.accentColor == accentColor &&
        other.address == address &&
        other.shippingAddress == shippingAddress &&
        collectionEquals(other.locations, locations) &&
        collectionEquals(other.history, history) &&
        collectionEquals(other.colorScheme, colorScheme) &&
        other.timeout == timeout &&
        other.apiUrl == apiUrl;
  }

  @override
  int get hashCode {
    return Object.hashAll([
      name,
      count,
      value,
      flag,
      nickname,
      optionalCount,
      status,
      priority,
      tags,
      scores,
      categories,
      createdAt,
      themeColor,
      icon,
      modifiedAt,
      accentColor,
      address,
      shippingAddress,
      locations,
      history,
      colorScheme,
      timeout,
      apiUrl,
    ]);
  }
}

// ============================================================================
// IGNORE DIRECTIVE - Skip specific fields
// ============================================================================

/// Use 'ignore' directive to skip serialization for specific fields
@immutable
class PartialSerialization {
  final String id;
  final String name;
  final String
      cachedValue; // ignore - will be passed through without conversion

  const PartialSerialization({
    required this.id,
    required this.name,
    required this.cachedValue,
  });

  PartialSerialization copyWith({
    String? id,
    String? name,
    String? cachedValue,
  }) {
    return PartialSerialization(
      id: id ?? this.id,
      name: name ?? this.name,
      cachedValue: cachedValue ?? this.cachedValue,
    );
  }

  Map<String, dynamic> toMap() {
    return {
      'id': id,
      'name': name,
      'cached_value': cachedValue,
    };
  }

  factory PartialSerialization.fromMap(Map<String, dynamic> map) {
    T cast<T>(String k) => map[k] is T
        ? map[k] as T
        : throw ArgumentError.value(map[k], k, '$T ← ${map[k].runtimeType}');
    return PartialSerialization(
      id: cast<String?>('id') ?? '',
      name: cast<String?>('name') ?? '',
      cachedValue: cast<String?>('cached_value') ?? '',
    );
  }

  String toJson() => json.encode(toMap());

  factory PartialSerialization.fromJson(String source) =>
      PartialSerialization.fromMap(json.decode(source) as Map<String, dynamic>);

  @override
  String toString() => '''PartialSerialization(
      id: $id,
      name: $name,
      cachedValue: $cachedValue
      )''';

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) return true;

    return other is PartialSerialization &&
        other.id == id &&
        other.name == name &&
        other.cachedValue == cachedValue;
  }

  @override
  int get hashCode => Object.hash(id, name, cachedValue);
}
